import{_ as e,o,c as a,a2 as s}from"./chunks/framework.ChIlRNAd.js";const p=JSON.parse('{"title":"Notifications and webhooks","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/notifications.md","filePath":"en/guide/notifications.md"}'),n={name:"en/guide/notifications.md"};function r(i,t,d,l,h,c){return o(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="notifications-and-webhooks" tabindex="-1">Notifications and webhooks <a class="header-anchor" href="#notifications-and-webhooks" aria-label="Permalink to &quot;Notifications and webhooks&quot;">​</a></h1><p>Nid tells you about important events in three ways: the header <strong>bell</strong>, <strong>toasts</strong> (temporary messages on screen) and <strong>webhooks</strong> to your services. Settings are in <strong>Settings › Notifications &amp; webhooks</strong>.</p><hr><h2 id="notification-bell" tabindex="-1">Notification bell <a class="header-anchor" href="#notification-bell" aria-label="Permalink to &quot;Notification bell&quot;">​</a></h2><p>The bell, at the top right of every page, shows the number of unread notifications. It opens a panel with the latest notifications:</p><ul><li>clicking a notification marks it as read;</li><li><strong>Mark all as read</strong>;</li><li><strong>Clear read</strong>: after confirmation, permanently deletes read notifications;</li><li>a row&#39;s delete button deletes that notification.</li></ul><hr><h2 id="notification-preferences" tabindex="-1">Notification preferences <a class="header-anchor" href="#notification-preferences" aria-label="Permalink to &quot;Notification preferences&quot;">​</a></h2><p>In <strong>Settings › Notifications &amp; webhooks</strong>, each event has two switches: <strong>In-app</strong> (in the bell) and <strong>Toast</strong> (a temporary message on screen). Each change is saved immediately.</p><table tabindex="0"><thead><tr><th>Event</th><th>When</th></tr></thead><tbody><tr><td><strong>Weekly report</strong></td><td>activity summary every Monday</td></tr><tr><td><strong>Task completed</strong></td><td>a task (bulk action, backup, rule) ends</td></tr><tr><td><strong>Task failed</strong></td><td>a task fails</td></tr><tr><td><strong>Rule run</strong></td><td>an automatic rule runs</td></tr><tr><td><strong>Storage alert</strong></td><td>archive storage nears its limit</td></tr><tr><td><strong>Integrity alert</strong></td><td>a problem is found in the archives</td></tr></tbody></table><hr><h2 id="webhooks" tabindex="-1">Webhooks <a class="header-anchor" href="#webhooks" aria-label="Permalink to &quot;Webhooks&quot;">​</a></h2><p>&quot;Sends events to Discord, Slack, ntfy or your own URL (HMAC signed).&quot;</p><h3 id="create-a-webhook" tabindex="-1">Create a webhook <a class="header-anchor" href="#create-a-webhook" aria-label="Permalink to &quot;Create a webhook&quot;">​</a></h3><p><strong>New webhook</strong> opens the form:</p><ul><li><strong>Name</strong>;</li><li><strong>URL</strong>;</li><li><strong>Type</strong>: <strong>Generic (HMAC)</strong>, <strong>Discord</strong>, <strong>Slack</strong>, <strong>ntfy</strong>;</li><li>for ntfy: <strong>ntfy user (optional)</strong> and <strong>ntfy password (optional)</strong>;</li><li><strong>Events</strong> (at least one):</li></ul><table tabindex="0"><thead><tr><th>Event</th><th>Matching preference</th></tr></thead><tbody><tr><td><code>job.completed</code></td><td>Task completed</td></tr><tr><td><code>job.failed</code></td><td>Task failed</td></tr><tr><td><code>rule.executed</code></td><td>Rule run</td></tr><tr><td><code>quota.warning</code></td><td>Storage alert</td></tr><tr><td><code>integrity.failed</code></td><td>Integrity alert</td></tr><tr><td><code>account.reauth_required</code></td><td>Gmail account to reconnect</td></tr></tbody></table><p>The weekly report is not sent by webhook.</p><h3 id="manage-webhooks" tabindex="-1">Manage webhooks <a class="header-anchor" href="#manage-webhooks" aria-label="Permalink to &quot;Manage webhooks&quot;">​</a></h3><p>Each webhook in the list shows its type and the status code of the last call (&quot;last call: 200&quot;). A switch turns it on or off without deleting it. Its menu offers <strong>Send a test</strong> and <strong>Delete</strong> (after confirmation).</p><h3 id="signature-generic-type" tabindex="-1">Signature (Generic type) <a class="header-anchor" href="#signature-generic-type" aria-label="Permalink to &quot;Signature (Generic type)&quot;">​</a></h3><p><strong>Generic (HMAC)</strong> webhooks add an <code>X-Webhook-Signature: sha256=…</code> header, an HMAC-SHA256 of the request body. Your server can check it to make sure the request comes from Nid.</p><hr><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><h3 id="discord" tabindex="-1">Discord <a class="header-anchor" href="#discord" aria-label="Permalink to &quot;Discord&quot;">​</a></h3><ol><li>In Discord: <strong>Channel settings</strong> → <strong>Integrations</strong> → <strong>Webhooks</strong> → <strong>New webhook</strong>, then copy the URL</li><li>In Nid, create a <strong>Discord</strong> webhook with that URL and pick the events</li></ol><h3 id="ntfy" tabindex="-1">ntfy <a class="header-anchor" href="#ntfy" aria-label="Permalink to &quot;ntfy&quot;">​</a></h3><p><a href="https://ntfy.sh" target="_blank" rel="noreferrer">ntfy</a> sends push notifications to your phone or browser.</p><ul><li><strong>Public topic</strong>: create an <strong>ntfy</strong> webhook with the URL <code>https://ntfy.sh/nid-alerts</code>, then subscribe to the same topic in the ntfy app.</li><li><strong>Protected topic</strong> (self-hosted ntfy server, for instance): enter your server URL (<code>https://ntfy.example.com/my-topic</code>) and the user / password fields; they are sent as <code>Authorization: Basic</code>. <strong>Send a test</strong> checks the authentication.</li></ul><div class="tip custom-block"><p class="custom-block-title">Self-hosted ntfy server</p><p>With access control (<code>auth-default-access: deny-all</code>), create a user and give it write access to the topic:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ntfy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myuser</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ntfy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> access</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myuser</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> write</span></span></code></pre></div></div><div class="warning custom-block"><p class="custom-block-title">Security</p><p>ntfy credentials are stored in plain text in the database. Use a dedicated account with minimal permissions (write-only on the relevant topic).</p></div>`,31)])])}const u=e(n,[["render",r]]);export{p as __pageData,u as default};
